//! Clap builder definitions only; validation and execution live elsewhere.

use clap::{
    Arg, ArgAction, Command,
    builder::{
        NonEmptyStringValueParser,
        styling::{AnsiColor, Effects, Styles},
    },
};
use std::{path::PathBuf, sync::OnceLock};

// The generated documentation is owned by built and contains unformatted names.
#[allow(clippy::doc_markdown, reason = "documentation is generated by built")]
mod built_info {
    include!(concat!(env!("OUT_DIR"), "/built.rs"));
}

/// Build the Pulse CLI without performing I/O.
#[must_use]
pub fn new() -> Command {
    let styles = Styles::styled()
        .header(AnsiColor::Yellow.on_default() | Effects::BOLD)
        .usage(AnsiColor::Green.on_default() | Effects::BOLD)
        .literal(AnsiColor::Blue.on_default() | Effects::BOLD)
        .placeholder(AnsiColor::Green.on_default());

    Command::new(env!("CARGO_PKG_NAME"))
        .version(env!("CARGO_PKG_VERSION"))
        .long_version(long_version())
        .author(env!("CARGO_PKG_AUTHORS"))
        .about(env!("CARGO_PKG_DESCRIPTION"))
        .styles(styles)
        .subcommand_required(true)
        .arg_required_else_help(true)
        .arg(arg_verbose())
        .arg(arg_color(
            "color",
            "Force colored output, overriding NO_COLOR",
        ))
        .arg(arg_color("no-color", "Disable colored output"))
        .subcommand(command_probe())
        .subcommand(
            Command::new("run")
                .about("Run autonomous HTTP monitoring")
                .arg(arg_path("config")),
        )
        .subcommand(command_enroll())
        .subcommand(command_config())
        .subcommand(
            Command::new("status")
                .about("Print local status as JSON (no network request)")
                .arg(arg_state_dir()),
        )
        .subcommand(command_community())
        .after_help(
            "Examples:\n  pulse config validate --file examples/pulse.toml\n  pulse run --config examples/pulse.toml\n  pulse probe http https://example.com",
        )
}

fn command_enroll() -> Command {
    Command::new("enroll")
        .about("Enroll with a compatible HTTPS control plane")
        .arg(
            Arg::new("server")
                .long("server")
                .value_name("HTTPS_URL")
                .help("HTTPS control-plane origin")
                .value_parser(NonEmptyStringValueParser::new())
                .required(true),
        )
        .arg(
            Arg::new("token")
                .long("token")
                .env("PULSE_TOKEN")
                .hide_env_values(true)
                .required(true)
                .value_parser(NonEmptyStringValueParser::new())
                .help("One-time enrollment token (prefer PULSE_TOKEN)"),
        )
        .arg(arg_state_dir())
        .arg(arg_ca())
}

fn command_config() -> Command {
    Command::new("config")
        .about("Inspect local configuration")
        .subcommand_required(true)
        .arg_required_else_help(true)
        .subcommand(
            Command::new("validate")
                .about("Parse TOML and validate local safety limits without network I/O")
                .arg(arg_path("file").required(false).default_value("pulse.toml")),
        )
}

fn command_community() -> Command {
    let mut command = Command::new("community")
        .about("Manage explicit public measurement participation")
        .subcommand_required(true);
    for operation in ["enable", "status", "disable"] {
        command = command.subcommand(Command::new(operation).arg(arg_state_dir()));
    }
    command
}

fn long_version() -> &'static str {
    static VERSION: OnceLock<String> = OnceLock::new();
    VERSION
        .get_or_init(|| {
            format!(
                "{} - {}",
                env!("CARGO_PKG_VERSION"),
                built_info::GIT_COMMIT_HASH.unwrap_or("unknown")
            )
        })
        .as_str()
}

fn command_probe() -> Command {
    Command::new("probe")
        .about("Execute one HTTP/HTTPS probe")
        .subcommand_required(true)
        .subcommand(
            Command::new("http")
                .about("HTTP/HTTPS GET with public-address policy")
                .arg(
                    Arg::new("target")
                        .value_name("URL")
                        .value_parser(NonEmptyStringValueParser::new())
                        .required(true),
                )
                .arg(
                    Arg::new("allow-private")
                        .long("allow-private")
                        .action(ArgAction::SetTrue)
                        .help("Explicitly allow private addresses; metadata remains forbidden"),
                ),
        )
}

fn arg_path(name: &'static str) -> Arg {
    Arg::new(name)
        .long(name)
        .value_name("FILE")
        .help("Local TOML configuration file")
        .value_parser(clap::value_parser!(PathBuf))
        .required(true)
}

fn arg_verbose() -> Arg {
    Arg::new("verbose")
        .short('v')
        .long("verbose")
        .help("Increase logging: -v INFO, -vv DEBUG, -vvv TRACE; RUST_LOG overrides")
        .action(ArgAction::Count)
        .global(true)
}

fn arg_color(name: &'static str, help: &'static str) -> Arg {
    Arg::new(name)
        .long(name)
        .help(help)
        .action(ArgAction::SetTrue)
        .conflicts_with(if name == "color" { "no-color" } else { "color" })
        .global(true)
}

fn arg_state_dir() -> Arg {
    Arg::new("state-dir")
        .long("state-dir")
        .value_parser(clap::value_parser!(PathBuf))
        .default_value(".pulse")
        .help("Private local state directory")
}
fn arg_ca() -> Arg {
    Arg::new("ca-file")
        .long("ca-file")
        .value_parser(clap::value_parser!(PathBuf))
        .help("Additional trusted control-plane CA in PEM format")
}
